import java.util.*;

enum Day { MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY }

EnumSet<Day> workingDays = EnumSet.of(Day.MONDAY, Day.TUESDAY, Day.WEDNESDAY);
System.out.println(workingDays);

import java.util.*;

enum Day { MONDAY, TUESDAY, WEDNESDAY }

EnumMap<Day, String> tasks = new EnumMap<>(Day.class);
tasks.put(Day.MONDAY, "Coding");
tasks.put(Day.TUESDAY, "Testing");
System.out.println(tasks);

for(Map.Entry<Day, String> entry : tasks.entrySet()){
    System.out.println(entry.getKey() + " -> " + entry.getValue());
}
